<script setup lang="ts">
import {ref,onMounted,computed} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,correction,type Paper,type Question} from './api'
import Workspace from './Workspace.vue'
import Analytics from './Analytics.vue'
import Knowledge from './Knowledge.vue'
import Backups from './Backups.vue'
import PdfViewer from './PdfViewer.vue'
import AiSettings from './AiSettings.vue'
import CollectionSettings from './CollectionSettings.vue'
const importKind=ref('full'),importModule=ref(''),importSubtype=ref('')
const view=ref('library'),start=ref<number>(),startFilter=ref('all'),workspace=ref<InstanceType<typeof Workspace>>()
const papers=ref<Paper[]>([]),paper=ref<Paper>(),busy=ref(false),error=ref(''),page=ref(1),search=ref('')
const shown=computed(()=>papers.value.filter(p=>p.title.includes(search.value)))
const counts=computed(()=>{const rows=paper.value?.questions||[];return {total:rows.length,keys:rows.filter(q=>q.correct_answer).length,answers:rows.filter(q=>q.user_answer).length,correct:rows.filter(q=>q.answer_status==='correct').length,wrong:rows.filter(q=>q.answer_status==='wrong').length}})
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function refresh(){papers.value=await api<Paper[]>('/papers')}
async function navigate(target:string){if(workspace.value&&!await workspace.value.leave())return;view.value=target;localStorage.setItem('lastView',target)}
async function open(id:string){await run(async()=>{paper.value=await api<Paper>('/papers/'+id);view.value='check';page.value=1;localStorage.setItem('lastPaper',id)})}
async function goWorkspace(id:string,number?:number,filter='all'){if(workspace.value&&!await workspace.value.leave())return;await open(id);start.value=number;startFilter.value=filter;await navigate('workspace')}
async function removeQuestion(q:Question){try{await ElMessageBox.confirm('Delete this question and its review?', 'Confirm deletion',{type:'warning'})}catch{return}await run(async()=>{await api('/questions/'+q.id,{method:'DELETE'});paper.value!.questions=paper.value!.questions!.filter(row=>row.id!==q.id)})}
async function remove(p:Paper){try{await ElMessageBox.confirm('将删除本卷和关联笔记。这是本地操作，请先备份。','删除试卷',{type:'warning'})}catch{return}await run(async()=>{await api('/papers/'+p.id,{method:'DELETE'});await refresh();if(paper.value?.id===p.id)paper.value=undefined})}
async function upload(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;await run(async()=>{const form=new FormData();form.append('file',file);form.append('collection_kind',importKind.value);if(importKind.value==='topic'){form.append('module',importModule.value);form.append('subtype',importSubtype.value)}const p=await api<Paper & {duplicate?:boolean}>('/papers/import',{method:'POST',body:form});if(p.duplicate)ElMessage.info('该原卷已存在，已保留原有记录');await refresh();paper.value=await api<Paper>('/papers/'+p.id);view.value='check';localStorage.setItem('lastPaper',p.id)});input.value=''}
async function save(q:Question){await run(async()=>{const saved=await api<Question>('/questions/'+q.id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(correction(q))});Object.assign(q,saved);ElMessage.success('校正已写入本地数据库')})}
async function add(){if(!paper.value)return;await run(async()=>{const rows=paper.value!.questions||[],number=Math.max(0,...rows.map(q=>q.number))+1;const q=await api<Question>('/papers/'+paper.value!.id+'/questions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({number,module:'待核对',subtype:'',page_start:page.value,page_end:page.value})});rows.push(q);paper.value!.questions=rows})}
async function confirm(){await run(async()=>{const p=await api<Paper>('/papers/'+paper.value!.id+'/confirm',{method:'POST'});paper.value!.parse_status=p.parse_status;ElMessage.success('已确认导入');await refresh();start.value=undefined;await navigate('workspace')})}
onMounted(()=>run(async()=>{await refresh();const id=localStorage.getItem('lastPaper');if(id&&papers.value.some(p=>p.id===id)){paper.value=await api<Paper>('/papers/'+id);view.value=localStorage.getItem('lastView')==='workspace'?'workspace':'check'}}))
</script>
<template>
<header><div><small>本地 · 私有数据</small><h1>行测复盘工作台</h1></div><nav><el-button @click="navigate('library');refresh()">试卷库</el-button><el-button @click="navigate('knowledge')">笔记库</el-button><el-button @click="navigate('backups')">备份恢复</el-button><el-button @click="navigate('ai-settings')">AI 设置</el-button></nav></header>
<main v-loading="busy"><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/>
<template v-if="view==='library'"><h2>从一份原卷开始</h2><p>上传 PDF → 核对解析 → 逐题复盘。原始 PDF 和笔记保存在本机。</p><div class="toolbar"><el-select v-model="importKind" aria-label="导入类型"><el-option value="full" label="完整试卷"/><el-option value="topic" label="专题题集 / 摘录"/></el-select><el-input v-if="importKind==='topic'" v-model="importModule" placeholder="模块（选填），例如：判断推理"/><el-input v-if="importKind==='topic'" v-model="importSubtype" placeholder="题型（选填），例如：图形推理"/></div><label class="upload">选择 PDF（默认上限 30 MB）<input type="file" accept=".pdf" :disabled="busy" @change="upload"/></label><el-input v-model="search" placeholder="搜索试卷标题"/><p v-if="!shown.length">暂无试卷，请上传实际 PDF。</p><article v-for="p in shown" :key="p.id"><h3>{{p.title}} <el-tag>{{p.collection_kind==='topic'?'专题题集':'整卷'}}</el-tag></h3><p>{{p.page_count}} 页 · {{p.total||0}} 题 · 完成 {{p.completed||0}} 题 · 正确率 {{p.accuracy==null?'无法计算':p.accuracy+'%'}} · {{p.parse_status==='confirmed'?'已确认':'待人工核对'}}</p><el-button @click="open(p.id)">原卷与校验</el-button><el-button @click="goWorkspace(p.id)">继续复盘</el-button><el-button @click="open(p.id).then(()=>navigate('analytics'))">统计</el-button><el-button type="danger" plain @click="remove(p)">删除</el-button></article></template>
<template v-else-if="paper&&view==='check'"><h2>{{paper.title}}</h2><p>{{paper.page_count}} 页 · {{counts.total}} 题 · 标准答案 {{counts.keys}} 条 · 个人答案 {{counts.answers}} 条 · 正确 {{counts.correct}} / 错误 {{counts.wrong}}（待确认数据）</p><el-alert title="请先核对题数、模块及答案。缺失答案不会被记为答错；候选题号与跨页范围均须核对。" type="warning" :closable="false"/><ul><li v-for="w in paper.warnings" :key="w">{{w}}</li></ul><div class="toolbar"><el-button @click="navigate('workspace')">进入复盘工作台</el-button><el-button @click="navigate('analytics')">本卷统计</el-button></div>
<CollectionSettings :key="paper.id" :paper="paper" @saved="open(paper!.id)"/><div class="layout"><PdfViewer :key="paper.id" :url="'/api/papers/'+paper.id+'/pdf'" :page="page"/><section class="corrections"><div class="toolbar"><el-button @click="add">手工添加题目</el-button><el-button type="primary" @click="confirm">确认导入</el-button></div><p v-if="!paper.questions?.length">未识别题目，可保留原卷浏览并手工建题。</p><article v-for="q in paper.questions" :key="q.id"><div class="toolbar"><strong>第 {{q.number}} 题</strong><el-button @click="page=q.page_start">查看原页</el-button><span>{{q.answer_status}}</span><el-button type="danger" plain @click="removeQuestion(q)">删除误识别题目</el-button></div><label>题号<el-input-number v-model="q.number" :min="1"/></label><label>模块<el-input v-model="q.module"/></label><label>二级题型<el-input v-model="q.subtype" placeholder="无法确定时留空"/></label><label>标准答案<el-select v-model="q.correct_answer" clearable placeholder="未知"><el-option v-for="a in ['A','B','C','D']" :key="a" :value="a"/></el-select></label><label>我的答案<el-select v-model="q.user_answer" clearable placeholder="未知"><el-option v-for="a in ['A','B','C','D','未作答']" :key="a" :value="a"/></el-select></label><label>起始页<el-input-number v-model="q.page_start" :min="1" :max="paper.page_count"/></label><label>终止页<el-input-number v-model="q.page_end" :min="q.page_start" :max="paper.page_count"/></label><ul class="warnings"><li v-for="w in q.warnings" :key="w">{{w}}</li></ul><el-checkbox v-model="q.checked">已对照原卷核对本题</el-checkbox><el-button :disabled="busy" @click="save(q)">保存校正 / 重试</el-button></article></section></div></template>
<template v-else-if="paper&&view==='workspace'"><div class="toolbar"><h2>{{paper.title}}</h2><el-button @click="navigate('check')">校验原卷</el-button><el-button @click="navigate('analytics')">本卷统计</el-button></div><Workspace :key="paper.id+':'+(start||'')+':'+startFilter" ref="workspace" :paper-id="paper.id" :start="start" :start-filter="startFilter"/></template>
<Analytics v-else-if="paper&&view==='analytics'" :paper-id="paper.id" @open-filter="f=>goWorkspace(paper!.id,undefined,f)"/>
<AiSettings v-else-if="view==='ai-settings'"/><Knowledge v-else-if="view==='knowledge'" @open="goWorkspace"/>
<Backups v-else-if="view==='backups'" @restored="()=>{paper=undefined;view='library';refresh()}"/>
</main><footer>数据位置：data/review.sqlite3 与 data/uploads/。请定期导出完整 JSON 备份，私下保管原卷与个人笔记。</footer>
</template>
